using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class ExpenseRepository(NamaaDbContext db):IExpenseRepository{public Task<bool>ExistsByExpenseNumberAsync(string value,CancellationToken cancellationToken=default)=>db.Expenses.AsNoTracking().AnyAsync(e=>e.ExpenseNumber==value,cancellationToken);public Task<Expense?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.Expenses.AsNoTracking().SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public Task<Expense?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.Expenses.SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public async Task<IReadOnlyList<Expense>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.Expenses.AsNoTracking().OrderBy(e=>e.Id).ToListAsync(cancellationToken);public async Task AddAsync(Expense entity,CancellationToken cancellationToken=default)=>await db.Expenses.AddAsync(entity,cancellationToken);}
